    function _releaseEpochCapacity(uint256 counter, uint256 amount, uint256 epoch, uint256 activeEpoch)
        private
        pure
        returns (uint256)
    {
        if (epoch != activeEpoch || amount == 0) {
            return counter;
        }
        return amount >= counter ? 0 : counter - amount;
    }

