        uint256 currentEpoch\\n    );\\n    event EpochCutoffChangeScheduled(\\n        uint256 oldEpochCutoffOffset,\\n        uint256 newEpochCutoffOffset,\\n        uint256 pendingNewCutoffStartTimestamp,\\n        uint256 currentEpoch\\n    );\\n    event MintFeeSet(uint256 oldFee, uint256 newFee);\\n    event MintExchangeRateCheckFailed(\\n        uint256 indexed epoch,\\n        uint256 lastEpochRate,\\n        uint256 newRate\\n    );\\n    event MintExchangeRateSet(\\n        uint256 indexed epoch,\\n        uint256 oldRate,\\n        uint256 newRate\\n    );\\n    event MintExchangeRateOverridden(\\n        uint256 indexed epoch,\\n        uint256 oldRate,\\n        uint256 newRate,\\n        uint256 lastSetMintExchangeRate\\n    );\\n\\n    event PendingRedemptions(uint256 remainingRedemptions);\\n\\n    event MinimumRedeemAmountFiatSet(uint256 oldMinimum, uint256 newMinimum);\\n\\n    error CollateralZeroAddress();\\n    error UltraZeroAddress();\\n    error KycZeroAddress();\\n    error MinimumDepositAmountTooSmall();\\n    error MintRequestAmountTooSmall();\\n    error MintExceedsRateLimit();\\n    error NoUltraToClaim();\\n    error ExchangeRateNotSet();\\n    error AssetRecipientZeroAddress();\\n    error AssetSenderZeroAddress();\\n    error RedeemAmountCannotBeZero();\\n    error RedeemExceedsRateLimit();\\n    error WithdrawRequestAmountTooSmall();\\n    error MustServicePastEpoch();\\n    error CollateralRedemptionTooSmall();\\n    error CannotServiceFutureEpoch();\\n    error KYCNotApproved();\\n    error MintFeeTooLarge();\\n    error ZeroExchangeRate();\\n    error EpochNotElapsed();\\n    error EpochExchangeRateAlreadySet();\\n    error EpochStartInFuture();\\n    error EpochStartNotAlignedToCutoff();\\n    error InvalidEpochCutoffOffset();\\n    error EpochCutoffOffsetUnchanged();\\n    error UnauthorizedFiatManager();\\n}\\n\"},\"contracts\/Ultra\/KYC.sol\":{\"content\":\"\/\/ SPDX-License-Identifier: MIT\\npragma solidity ^0.8.0;\\n\\nimport \\\".\/interfaces\/IKYC.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/access\/AccessControlEnumerableUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/proxy\/utils\/UUPSUpgradeable.sol\\\";\\n\\n\/**\\n * @title KYCUltra Contract\\n * @notice This contract manages KYC (Know Your Customer) verification for the Ultra token system\\n * @dev UUPS upgradeable. Inherits from IKYC, AccessControlEnumerableUpgradeable and UUPSUpgradeable\\n *      to handle KYC status and role-based access control\\n *\/\\ncontract KYCUltra is IKYC, AccessControlEnumerableUpgradeable, UUPSUpgradeable {\\n    error ZeroAddress();\\n\\n    bytes32 public constant MINTER_ADMIN = keccak256(\\\"MINTER_ADMIN\\\");\\n    mapping(address =\u003e User) public users;\\n    string public whitelistName;\\n    \\n    struct ExternalKYCContract {\\n        address contractAddress;\\n        bytes4 functionSelector;\\n    }\\n\\n    ExternalKYCContract[] public externalKYCContracts;\\n\\n    event ExternalKYCContractAdded(address indexed contractAddress, bytes4 functionSelector);\\n    event ExternalKYCContractRemoved(address indexed contractAddress, bytes4 functionSelector);\\n\\n    \/\/\/ @custom:oz-upgrades-unsafe-allow constructor\\n    constructor() {\\n        _disableInitializers();\\n    }\\n\\n    \/**\\n     * @notice Initializes the KYC contract with a whitelist name and admin roles\\n     * @dev Sets up the initial state with minter and default admin roles\\n     * @param _whitelistName Name of the whitelist for identification\\n     * @param minterAdmin Address that will receive the MINTER_ADMIN role\\n     * @param defaultAdmin Address that will receive the DEFAULT_ADMIN_ROLE\\n     *\/\\n    function initialize(string memory _whitelistName, address minterAdmin, address defaultAdmin) public initializer {\\n        if (minterAdmin == address(0)) revert ZeroAddress();\\n        if (defaultAdmin == address(0)) revert ZeroAddress();\\n\\n        __AccessControlEnumerable_init();\\n        __UUPSUpgradeable_init();\\n\\n        whitelistName = _whitelistName;\\n        _grantRole(MINTER_ADMIN, minterAdmin);\\n        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);\\n    }\\n\\n    \/**\\n     * @notice Authorizes an upgrade to a new implementation\\n     * @dev Can only be called by an account with DEFAULT_ADMIN_ROLE\\n     * @param newImplementation Address of the new implementation contract\\n     *\/\\n    function _authorizeUpgrade(address newImplementation) internal override onlyRole(DEFAULT_ADMIN_ROLE) {\\n    }\\n\\n    \/**\\n     * @notice Adds an external KYC contract to check for KYC status\\n     * @dev Can only be called by accounts with DEFAULT_ADMIN_ROLE\\n     * @param kycContract Address of the external KYC contract\\n     * @param functionSelector Function selector to call on the external contract\\n     *\/\\n    function addExternalKYCContract(address kycContract, bytes4 functionSelector)\\n        external\\n        onlyRole(DEFAULT_ADMIN_ROLE)\\n    {\\n        require(kycContract != address(0), \\\"KYC: contract address cannot be zero\\\");\\n        externalKYCContracts.push(\\n            ExternalKYCContract({\\n                contractAddress: kycContract,\\n                functionSelector: functionSelector\\n            })\\n        );\\n        emit ExternalKYCContractAdded(kycContract, functionSelector);\\n    }\\n\\n    \/**\\n     * @notice Removes an external KYC contract from the list\\n     * @dev Can only be called by accounts with DEFAULT_ADMIN_ROLE\\n     * @param index Index of the external KYC contract to remove\\n     *\/\\n    function removeExternalKYCContract(uint256 index) external onlyRole(DEFAULT_ADMIN_ROLE) {\\n        require(index \u003c externalKYCContracts.length, \\\"Index out of bounds\\\");\\n        ExternalKYCContract memory removedContract = externalKYCContracts[index];\\n        externalKYCContracts[index] = externalKYCContracts[externalKYCContracts.length - 1];\\n        externalKYCContracts.pop();\\n        emit ExternalKYCContractRemoved(removedContract.contractAddress, removedContract.functionSelector);\\n    }\\n\\n    \/**\\n     * @notice Retrieves the list of external KYC contracts\\n     * @return Array of ExternalKYCContract structs containing contract addresses and function selectors\\n     *\/\\n    function getExternalKYCContracts() external view returns (ExternalKYCContract[] memory) {\\n        return externalKYCContracts;\\n    }\\n\\n    \/**\\n     * @notice Grants KYC status to a single user\\n     * @dev Can only be called by accounts with MINTER_ADMIN role\\n     * @param user Address of the user to grant KYC status\\n     *\/\\n    function grantKyc(address user) external onlyRole(MINTER_ADMIN) {\\n        _grantKyc(user);\\n    }\\n\\n    \/**\\n     * @notice Grants KYC status to multiple users in a single transaction\\n     * @dev Can only be called by accounts with MINTER_ADMIN role. Limited to 256 users per call\\n     * @param _users Array of addresses to grant KYC status\\n     *\/\\n    function grantKycInBulk(address[] calldata _users) external onlyRole(MINTER_ADMIN) {\\n        require(_users.length \u003c= 256, \\\"KYC: too many users\\\");\\n        for (uint256 i = 0; i \u003c _users.length; i++) {\\n            _grantKyc(_users[i]);\\n        }\\n    }\\n\\n    \/**\\n     * @notice Internal function to grant KYC status to a user\\n     * @dev Emits a GrantKyc event\\n     * @param user Address of the user to grant KYC status\\n     *\/\\n    function _grantKyc(address user) internal {\\n        users[user].isKYC = true;\\n        emit GrantKyc(user);\\n    }\\n\\n    \/**\\n     * @notice Revokes KYC status from a single user\\n     * @dev Can only be called by accounts with MINTER_ADMIN role\\n     * @param user Address of the user to revoke KYC status\\n     *\/\\n    function revokeKyc(address user) external onlyRole(MINTER_ADMIN) {\\n        _revokeKyc(user);\\n    }\\n\\n    \/**\\n     * @notice Revokes KYC status from multiple users in a single transaction\\n     * @dev Can only be called by accounts with MINTER_ADMIN role. Limited to 256 users per call\\n     * @param _users Array of addresses to revoke KYC status\\n     *\/\\n    function revokeKycInBulk(address[] calldata _users) external onlyRole(MINTER_ADMIN) {\\n        require(_users.length \u003c= 256, \\\"KYC: too many users\\\");\\n        for (uint256 i = 0; i \u003c _users.length; i++) {\\n            _revokeKyc(_users[i]);\\n        }\\n    }\\n\\n    \/**\\n     * @notice Internal function to revoke KYC status from a user\\n     * @dev Emits a RevokeKyc event\\n     * @param user Address of the user to revoke KYC status\\n     *\/\\n    function _revokeKyc(address user) internal {\\n        users[user].isKYC = false;\\n        emit RevokeKyc(user);\\n    }\\n\\n    \/**\\n     * @notice Bans a user from the system\\n     * @dev Can only be called by accounts with MINTER_ADMIN role\\n     * @param user Address of the user to ban\\n     *\/\\n    function ban(address user) external onlyRole(MINTER_ADMIN) {\\n        _ban(user, true);\\n    }\\n\\n    \/**\\n     * @notice Internal function to set the ban status of a user\\n     * @dev Emits a Banned event\\n     * @param user Address of the user to ban\/unban\\n     * @param status True to ban, false to unban\\n     *\/\\n    function _ban(address user, bool status) internal {\\n        users[user].isBanned = status;\\n        emit Banned(user, status);\\n    }\\n\\n    \/**\\n     * @notice Checks if a user has valid KYC status\\n     * @dev Checks internal KYC status and external KYC contracts\\n     * @param user Address of the user to check\\n     * @return bool True if the user has valid KYC status and is not banned\\n     *\/\\n    function isKYC(address user) external view override returns (bool) {\\n        return _isKycApproved(user);\\n    }\\n\\n    \/**\\n     * @notice Internal function to check if a user is approved in any external KYC contracts\\n     * @dev Calls each external contract using their specified function selector\\n     * @param user Address of the user to check\\n     * @return bool True if the user is approved in any external KYC contract\\n     *\/\\n    function _isApprovedInExternalContracts(address user) internal view returns (bool) {\\n        for (uint256 i = 0; i \u003c externalKYCContracts.length; i++) {\\n            ExternalKYCContract storage externalKYC = externalKYCContracts[i];\\n            (bool success, bytes memory result) = externalKYC.contractAddress.staticcall(\\n                abi.encodeWithSelector(externalKYC.functionSelector, user)\\n            );\\n            if (success \u0026\u0026 result.length \u003e= 32) {\\n                bool approved = abi.decode(result, (bool));\\n                if (approved) {\\n                    return true;\\n                }\\n            }\\n        }\\n        return false;\\n    }\\n\\n    \/**\\n     * @notice Evaluates whether a user passes the canonical KYC policy\\n     * @dev Rejects banned users, then accepts internal or external KYC approval\\n     * @param user Address of the user to check\\n     * @return bool True if the user has valid KYC status and is not banned\\n     *\/\\n    function _isKycApproved(address user) internal view returns (bool) {\\n        if (users[user].isBanned) {\\n            return false;\\n        }\\n        if (users[user].isKYC) {\\n            return true;\\n        }\\n        if (_isApprovedInExternalContracts(user)) {\\n            return true;\\n        }\\n        return false;\\n    }\\n\\n    \/**\\n     * @notice Checks KYC status for multiple users in a single call\\n     * @dev Uses the same policy as isKYC() for each address. Limited to 256 users per call\\n     * @param _users Array of addresses to check\\n     * @return Array of boolean values indicating KYC status for each user\\n     *\/\\n    function isKYCBulk(address[] calldata _users) external view returns (bool[] memory) {\\n        require(_users.length \u003c= 256, \\\"KYC: too many users\\\");\\n\\n        bool[] memory results = new bool[](_users.length);\\n\\n        for (uint256 i = 0; i \u003c _users.length; i++) {\\n            results[i] = _isKycApproved(_users[i]);\\n        }\\n\\n        return results;\\n    }\\n\\n    \/**\\n     * @notice Checks if a user is banned\\n     * @param user Address of the user to check\\n     * @return bool True if the user is banned\\n     *\/\\n    function isBanned(address user) external view override returns (bool) {\\n        return users[user].isBanned;\\n    }\\n\\n    \/**\\n     * @notice View function that reverts if the user is banned\\n     * @param user Address of the user to check\\n     *\/\\n    function onlyNotBanned(address user) external view {\\n        require(!users[user].isBanned, \\\"KYC: user is banned\\\");\\n    }\\n\\n    \/**\\n     * @notice View function that reverts if the user doesn\u0027t have valid KYC status\\n     * @param user Address of the user to check\\n     *\/\\n    function onlyKyc(address user) external view {\\n        require(_isKycApproved(user), \\\"KYC: user is not KYC\\\");\\n    }\\n}\\n\"},\"contracts\/Ultra\/Ultra.sol\":{\"content\":\"\/\/ SPDX-License-Identifier: MIT\\npragma solidity ^0.8.0;\\n\\nimport \\\"@openzeppelin\/contracts-upgradeable\/token\/ERC20\/extensions\/ERC20BurnableUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/access\/AccessControlEnumerableUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/proxy\/utils\/UUPSUpgradeable.sol\\\";\\nimport \\\".\/KYC.sol\\\";\\nimport \\\".\/interfaces\/IUltra.sol\\\";\\nimport \\\".\/UltraManager.sol\\\";\\nimport \\\"@openzeppelin\/contracts\/token\/ERC20\/utils\/SafeERC20.sol\\\";\\n\\n\/** \\n * @title Ultra Token Contract\\n * @notice This contract implements the Ultra token with KYC requirements, transfer limits, and clawback functionality\\n * @dev Inherits from UUPSUpgradeable, AccessControlEnumerableUpgradeable, and ERC20BurnableUpgradeable\\n *\/\\ncontract Ultra is \\n    UUPSUpgradeable,\\n    AccessControlEnumerableUpgradeable, \\n    ERC20BurnableUpgradeable,\\n    IUltra\\n{\\n    using SafeERC20 for IERC20;\\n\\n    \/\/ Custom errors\\n    error TransferFailed();\\n    error TransferToZeroAddress();\\n    error InvalidAddress();\\n    error InvalidAmount();\\n    error Unauthorized();\\n    error InvalidUltraManager();\\n    error UltraManagerNotSet();\\n\\n    bytes32 internal constant OPERATOR_ADMIN = keccak256(\\\"OPERATOR_ADMIN\\\");\\n    bytes32 public constant MINTER_ADMIN = keccak256(\\\"MINTER_ADMIN\\\");\\n    bytes32 internal constant SUPER_ADMIN = keccak256(\\\"SUPER_ADMIN\\\");\\n\\n    \/\/ KYC contract reference needs to be mutable\\n    KYCUltra public KYCContract;\\n    address internal _clawbackAdmin;\\n    UltraManager internal _ultraManager;\\n    mapping(address =\u003e uint256) internal _clawedBackAmount; \/\/ Keep track of amount clawed back for each user\\n\\n    uint256 public transferLimit; \/\/ Transfer limit in BPS\\n    uint256 public transferLimitPeriod; \/\/ Configurable period for transfer limits\\n    mapping(address =\u003e TransferTracker) internal _transferTrackers;\\n\\n    struct TransferTracker {\\n        uint256 totalAmount;\\n        uint256 periodStart;\\n    }\\n\\n    \/\/\/ @custom:oz-upgrades-unsafe-allow constructor\\n    constructor() {\\n        _disableInitializers();\\n    }\\n\\n    \/** \\n     * @notice Initializes the Ultra token contract\\n     * @dev Sets up the initial state of the contract including roles and configurations\\n     * @param name The name of the token\\n     * @param symbol The symbol of the token\\n     * @param operatorAdmin Address that will receive the OPERATOR_ADMIN role\\n     * @param minterAdmin Address that will receive the MINTER_ADMIN role\\n     * @param superAdmin Address that will receive the SUPER_ADMIN role and be set as clawback admin\\n     * @param defaultAdmin Address that will receive the DEFAULT_ADMIN_ROLE\\n     * @param kyc Address of the KYC contract\\n     *\/\\n    function initialize(\\n        string memory name,\\n        string memory symbol,\\n        address operatorAdmin,\\n        address minterAdmin,\\n        address superAdmin,\\n        address defaultAdmin,\\n        address kyc\\n    ) public initializer {\\n        if (operatorAdmin == address(0)) revert InvalidAddress();\\n        if (minterAdmin == address(0)) revert InvalidAddress();\\n        if (superAdmin == address(0)) revert InvalidAddress();\\n        if (defaultAdmin == address(0)) revert InvalidAddress();\\n        if (kyc == address(0)) revert InvalidAddress();\\n\\n        __ERC20_init(name, symbol);\\n        __ERC20Burnable_init();\\n        __AccessControlEnumerable_init();\\n        __UUPSUpgradeable_init();\\n\\n        _grantRole(OPERATOR_ADMIN, operatorAdmin);\\n        _grantRole(MINTER_ADMIN, minterAdmin);\\n        _grantRole(SUPER_ADMIN, superAdmin);\\n        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);\\n        _clawbackAdmin = superAdmin;\\n        KYCContract = KYCUltra(kyc);\\n        \\n        transferLimitPeriod = 24 hours;\\n    }\\n\\n    \/** \\n     * @notice Authorizes an upgrade to a new implementation\\n     * @dev Can only be called by an account with DEFAULT_ADMIN_ROLE\\n     * @param newImplementation Address of the new implementation contract\\n     *\/\\n    function _authorizeUpgrade(address newImplementation) internal override onlyRole(DEFAULT_ADMIN_ROLE) {\\n    }\\n\\n    \/** \\n     * @notice Returns the number of decimals used for token amounts\\n     * @dev Overrides the default 18 decimals to return 6\\n     * @return The number of decimals (6)\\n     *\/\\n    function decimals() public view virtual override returns (uint8) {\\n        return 6;\\n    }\\n\\n    \/** \\n     * @notice Sets the UltraManager contract address\\n     * @dev Can only be called by an account with OPERATOR_ADMIN role.\\n     *      Rejects zero address, EOAs, and contracts that do not expose the\\n     *      required manager views with a non-zero BPS denominator.\\n     * @param ultraManager The address of the new UltraManager contract\\n     *\/\\n    function setUltraManager(\\n        address ultraManager\\n    ) external onlyRole(OPERATOR_ADMIN) {\\n        if (ultraManager == address(0)) revert InvalidAddress();\\n        if (ultraManager.code.length == 0) revert InvalidUltraManager();\\n\\n        UltraManager candidate = UltraManager(ultraManager);\\n        try candidate.BPS_DENOMINATOR() returns (uint256 bps) {\\n            if (bps == 0) revert InvalidUltraManager();\\n        } catch {\\n            revert InvalidUltraManager();\\n        }\\n        try candidate.lastSetMintExchangeRate() returns (uint256) {\\n        } catch {\\n            revert InvalidUltraManager();\\n        }\\n\\n        address oldUltraManager = address(_ultraManager);\\n        _ultraManager = candidate;\\n        emit UltraManagerSet(oldUltraManager, ultraManager);\\n    }\\n\\n    \/**\\n     * @notice Returns the fiat value of an amount using the configured UltraManager\\n     * @dev Reverts with UltraManagerNotSet when the manager is unset, or\\n     *      InvalidUltraManager when BPS_DENOMINATOR is zero\\n     * @param amount Token amount to convert\\n     * @return fiatValue Amount converted using lastSetMintExchangeRate \/ BPS_DENOMINATOR\\n     *\/\\n    function _fiatValueFromManager(uint256 amount) internal view returns (uint256 fiatValue) {\\n        if (address(_ultraManager) == address(0)) revert UltraManagerNotSet();\\n\\n        uint256 bps = _ultraManager.BPS_DENOMINATOR();\\n        if (bps == 0) revert InvalidUltraManager();\\n\\n        fiatValue = (amount * _ultraManager.lastSetMintExchangeRate()) \/ bps;\\n    }\\n\\n    \/** \\n     * @notice Sets the clawback wallet address\\n     * @dev Can only be called by an account with SUPER_ADMIN role\\n     * @param clawbackAdmin The address of the new clawback wallet\\n     *\/\\n    function setClawbackWallet(\\n        address clawbackAdmin\\n    ) external onlyRole(SUPER_ADMIN) {\\n        if (clawbackAdmin == address(0)) revert TransferToZeroAddress();\\n        address oldClawbackWallet = _clawbackAdmin;\\n        _clawbackAdmin = clawbackAdmin;\\n        emit ClawbackWalletSet(oldClawbackWallet, clawbackAdmin);\\n    }\\n\\n    \/** \\n     * @notice Sets the KYC contract address\\n     * @dev Can only be called by an account with OPERATOR_ADMIN role\\n     * @param kyc The address of the new KYC contract\\n     *\/\\n    function setKYC(address kyc) external onlyRole(OPERATOR_ADMIN) {\\n        if (kyc == address(0)) revert InvalidAddress();\\n        address oldKYC = address(KYCContract);\\n        KYCContract = KYCUltra(kyc);\\n        emit KYCContractSet(oldKYC, kyc);\\n    }\\n\\n    \/** \\n     * @notice Claws back tokens from a specified address\\n     * @dev Can only be called by an account with SUPER_ADMIN role\\n     * @param from The address to claw back tokens from\\n     * @param amount The amount of tokens to claw back\\n     *\/\\n    function clawback(address from, uint256 amount) external onlyRole(SUPER_ADMIN) {\\n        if (from == address(0)) revert InvalidAddress();\\n        if (amount == 0) revert InvalidAmount();\\n        \\n        _transfer(from, _clawbackAdmin, amount);\\n        _clawedBackAmount[from] += amount;\\n\\n        emit TokensClawedBack(from, _msgSender(), amount);\\n    }\\n\\n    \/** \\n     * @notice Hook that is called before any token transfer\\n     * @dev Ensures real transfer participants are KYC approved unless the receiver is the clawback admin.\\n     *      Mint (from == address(0)) and burn (to == address(0)) skip KYC on the zero address.\\n     * @param from The sender address\\n     * @param to The receiver address\\n     * @param amount The amount of tokens being transferred\\n     *\/\\n    function _beforeTokenTransfer(\\n        address from,\\n        address to,\\n        uint256 amount\\n    ) internal override {\\n        super._beforeTokenTransfer(from, to, amount);\\n        if (to != _clawbackAdmin) {\\n            if (address(KYCContract) != address(0)) {\\n                if (from == address(0)) {\\n                    require(\\n                        KYCContract.isKYC(to),\\n                        \\\"Ultra: receiver needs to be KYC approved\\\"\\n                    );\\n                } else if (to == address(0)) {\\n                    require(\\n                        KYCContract.isKYC(from),\\n                        \\\"Ultra: sender needs to be KYC approved\\\"\\n                    );\\n                } else {\\n                    require(\\n                        KYCContract.isKYC(from) \u0026\u0026\\n                            KYCContract.isKYC(to),\\n                        \\\"Ultra: both sender and receiver need to be KYC approved\\\"\\n                    );\\n                }\\n            }\\n        }\\n    }\\n\\n    \/** \\n     * @notice Completes a transfer of tokens\\n     * @dev Can only be called by an account with MINTER_ADMIN role\\n     * @param to The recipient address\\n     * @param amount The amount of tokens to transfer\\n     *\/\\n    function completeTransfer(\\n        address to,\\n        uint256 amount\\n    ) external onlyRole(MINTER_ADMIN) {\\n        if (to == address(0)) revert InvalidAddress();\\n        if (amount == 0) revert InvalidAmount();\\n        bool success = super.transfer(to, amount);\\n        if (!success) revert TransferFailed();\\n    }\\n\\n    \/** \\n     * @notice Transfers tokens from one address to another\\n     * @dev Handles transfer limits and creates transfer promises if needed\\n     * @param from The sender address\\n     * @param recipient The recipient address\\n     * @param amount The amount of tokens to transfer\\n     * @return success Whether the transfer was successful\\n     *\/\\n    function transferFrom(\\n        address from,\\n        address recipient,\\n        uint256 amount\\n    ) public virtual override returns (bool) {\\n        if (recipient == address(0)) revert TransferToZeroAddress();\\n\\n        _beforeTokenTransfer(from, recipient, amount);\\n\\n        uint256 fiatValue = _fiatValueFromManager(amount);\\n\\n        _checkAndUpdateTransferTracker(from, fiatValue);\\n\\n        bool success;\\n        if (_transferTrackers[from].totalAmount \u003c= transferLimit) {\\n            success = super.transferFrom(from, recipient, amount);\\n            if (!success) revert TransferFailed();\\n            return success;\\n        } else {\\n            success = super.transferFrom(from, address(_ultraManager), amount);\\n            if (!success) revert TransferFailed();\\n            _ultraManager.createTransferPromise(from, recipient, amount);\\n            return success;\\n        }\\n    }\\n\\n    \/** \\n     * @notice Transfers tokens from an address through the manager\\n     * @dev Can only be called by an account with MINTER_ADMIN role\\n     * @param from The sender address\\n     * @param recipient The recipient address\\n     * @param amount The amount of tokens to transfer\\n     * @return success Whether the transfer was successful\\n     *\/\\n    function transferFromManager(\\n        address from,\\n        address recipient,\\n        uint256 amount\\n    ) external onlyRole(MINTER_ADMIN) returns (bool) {\\n        bool success = super.transferFrom(from, recipient, amount);\\n        if (!success) revert TransferFailed();\\n        return success;\\n    }\\n\\n    \/** \\n     * @notice Transfers tokens to another address\\n     * @dev Handles transfer limits and creates transfer promises if needed\\n     * @param recipient The recipient address\\n     * @param amount The amount of tokens to transfer\\n     * @return success Whether the transfer was successful\\n     *\/\\n    function transfer(\\n        address recipient,\\n        uint256 amount\\n    ) public virtual override returns (bool) {\\n        if (recipient == address(0)) revert TransferToZeroAddress();\\n\\n        _beforeTokenTransfer(_msgSender(), recipient, amount);\\n\\n        uint256 fiatValue = _fiatValueFromManager(amount);\\n\\n        _checkAndUpdateTransferTracker(_msgSender(), fiatValue);\\n\\n        bool success;\\n        if (_transferTrackers[_msgSender()].totalAmount \u003c= transferLimit) {\\n            success = super.transfer(recipient, amount);\\n            if (!success) revert TransferFailed();\\n            return success;\\n        } else {\\n            success = super.transfer(address(_ultraManager), amount);\\n            if (!success) revert TransferFailed();\\n            _ultraManager.createTransferPromise(_msgSender(), recipient, amount);\\n            return success;\\n        }\\n    }\\n\\n    \/** \\n     * @notice Mints new tokens\\n     * @dev Can only be called by an account with MINTER_ADMIN role\\n     * @param to The address that will receive the minted tokens\\n     * @param amount The amount of tokens to mint\\n     *\/\\n    function mint(address to, uint256 amount) public virtual onlyRole(MINTER_ADMIN) {\\n        _mint(to, amount);\\n    }\\n\\n    \/** \\n     * @notice Mints new tokens with a promise ID\\n     * @dev Can only be called by an account with MINTER_ADMIN role\\n     * @param to The address that will receive the minted tokens\\n     * @param amount The amount of tokens to mint\\n     * @param promiseId The ID of the associated promise\\n     *\/\\n    function mint(address to, uint256 amount, string memory promiseId) public virtual onlyRole(MINTER_ADMIN) {\\n        _mint(to, amount);\\n        emit MintCompleted(to, amount, promiseId);\\n    }\\n\\n    \/** \\n     * @notice Sets the transfer limit\\n     * @dev Can only be called by an account with OPERATOR_ADMIN role\\n     * @param newLimit The new transfer limit in BPS\\n     *\/\\n    function setTransferLimit(uint256 newLimit) external onlyRole(OPERATOR_ADMIN) {\\n        uint256 oldLimit = transferLimit;\\n        transferLimit = newLimit;\\n        emit TransferLimitSet(oldLimit, newLimit);\\n    }\\n\\n    \/** \\n     * @notice Sets the transfer limit period\\n     * @dev Can only be called by an account with OPERATOR_ADMIN role\\n     * @param newPeriod The new transfer limit period in seconds\\n     *\/\\n    function setTransferLimitPeriod(uint256 newPeriod) external onlyRole(OPERATOR_ADMIN) {\\n        if (newPeriod == 0) revert InvalidAmount();\\n        uint256 oldPeriod = transferLimitPeriod;\\n        transferLimitPeriod = newPeriod;\\n        emit TransferLimitPeriodSet(oldPeriod, newPeriod);\\n    }\\n\\n    \/** \\n     * @notice Updates the transfer tracker for an account\\n     * @dev Internal function to track transfer amounts within periods\\n     * @param account The address to track\\n     * @param amount The amount to add to the tracker\\n     *\/\\n    function _checkAndUpdateTransferTracker(address account, uint256 amount) internal {\\n        TransferTracker storage tracker = _transferTrackers[account];\\n        \\n        if (tracker.periodStart == 0) {\\n            tracker.periodStart = block.timestamp;\\n            tracker.totalAmount = amount;\\n            return;\\n        }\\n        \\n        if (block.timestamp \u003e= tracker.periodStart + transferLimitPeriod) {\\n            tracker.totalAmount = amount;\\n            tracker.periodStart = block.timestamp;\\n        } else {\\n            tracker.totalAmount += amount;\\n        }\\n    }\\n}\\n\"},\"contracts\/Ultra\/UltraManager.sol\":{\"content\":\"\/\/ SPDX-License-Identifier: MIT\\npragma solidity ^0.8.0;\\n\\nimport \\\".\/interfaces\/IUltraManager.sol\\\";\\nimport \\\".\/Ultra.sol\\\";\\nimport \\\".\/KYC.sol\\\";\\nimport \\\"@openzeppelin\/contracts\/token\/ERC20\/ERC20.sol\\\";\\nimport \\\"@openzeppelin\/contracts\/token\/ERC20\/extensions\/IERC20Metadata.sol\\\";\\nimport \\\"@openzeppelin\/contracts\/token\/ERC20\/utils\/SafeERC20.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/proxy\/utils\/UUPSUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/access\/AccessControlEnumerableUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/security\/PausableUpgradeable.sol\\\";\\nimport \\\"@openzeppelin\/contracts-upgradeable\/security\/ReentrancyGuardUpgradeable.sol\\\";\\n\\n\/**\\n * @title UltraManager Production Contract\\n * @notice This contract manages the minting, redemption, and transfer processes for the Ultra token in production\\n * @dev Inherits from UUPSUpgradeable, AccessControlEnumerableUpgradeable, PausableUpgradeable, and ReentrancyGuardUpgradeable.\\n *      The dealing cutoff is fixed at whatever \`initialize\` seeded or \`initializeEpochCutoffOffset\`\\n *      derived.\\n *\/\\ncontract UltraManager is\\n    UUPSUpgradeable,\\n    AccessControlEnumerableUpgradeable,\\n    PausableUpgradeable,\\n    ReentrancyGuardUpgradeable,\\n    IUltraManager\\n{\\n    using SafeERC20 for IERC20;\\n\\n    \/\/ ERC20 token used to Mint ULTRA with\\n    IERC20 internal _collateral;\\n\\n    \/\/ ULTRA contract\\n    Ultra internal _ultra;\\n\\n    \/\/ Unused KYC contract, any KYC-related will rely on Ultra\u0027s KYC\\n    KYCUltra internal _kyc;\\n\\n    \/\/ The address to which the \`collateral\` is sent\\n    address internal _assetRecipient;\\n\\n    \/\/ The address to which fees are sent\\n    address internal _feeRecipient;\\n\\n    \/\/ The address from which redemptions are processed\\n    address internal _assetSender;\\n\\n    \/\/ Nested mapping containing mint requests for an epoch\\n    \/\/ { \u003cepoch\u003e : {\u003cuser\u003e : \u003ccollateralAmount\u003e }\\n    mapping(uint256 =\u003e mapping(address =\u003e uint256)) internal _mintRequestsPerEpoch;\\n\\n    struct RedemptionRequest {\\n        address redeemer;\\n        uint256 amountUltra;\\n        uint256 epoch;\\n        bool processing;\\n    }\\n\\n    \/\/ UNUSED VARIABLE\\n    RedemptionRequest[] internal _redemptionQueue;\\n\\n    \/\/ UNUSED STRUCT DEF, REQUIRED FOR UNUSED VAR BELOW\\n    struct RedemptionRequests {\\n        \/\/ Total ULTRA burned in the epoch\\n        uint256 totalBurned;\\n        \/\/ Mapping from address to amount of ULTRA address burned\\n        mapping(address =\u003e uint256) addressToBurnAmt; \/\/ Stores the amount of tokens burned for redemption\\n        mapping(address =\u003e uint256) redeemerToIndex; \/\/ Stores the index of the redeemer in the queue\\n        mapping(address =\u003e bool) redeemerToProcessing;\\n    }\\n\\n    \/\/ UNUSED VARIABLE\\n    mapping(uint256 =\u003e RedemptionRequests) internal _redemptionInfoPerEpoch;\\n\\n    \/\/ Mapping used for getting the exchange rate during a given epoch\\n    mapping(uint256 =\u003e uint256) internal _epochToExchangeRate;\\n\\n    mapping(address =\u003e mapping(address =\u003e uint256)) public transferPromises;\\n    \/\/ Minimum amount that must be deposited to mint ULTRA\\n\\n    \/\/ Denoted in decimals of \`collateral\`\\n    uint256 public minimumDepositAmount;\\n\\n    \/\/ Minting fee specified in basis points\\n    uint256 public mintFee;\\n\\n    \/\/ Minimum amount that must be redeemed for a withdraw request\\n    uint256 public minimumRedeemAmountFiat;\\n\\n    \/\/ Maximum amount that can be minted during an epoch\\n    uint256 public mintLimit;\\n\\n    \/\/ Amount already minted during the \`currentEpoch\`\\n    uint256 internal _currentMintAmount;\\n\\n    \/\/ Epoch that contract is currently in\\n    uint256 public currentEpoch;\\n\\n    \/\/ Duration of an epoch in seconds\\n    uint256 internal _epochDuration;\\n\\n    \/\/ Timestamp of the start of \`currentEpoch\`\\n    uint256 internal _currentEpochStartTimestamp;\\n\\n    \/\/ Timestamp of the contract start\\n    uint256 private _contractStartTimestamp;\\n\\n    \/\/ \`exchangeRate\` at start of \`currentEpoch\`\\n    uint256 public lastSetMintExchangeRate;\\n\\n    \/\/ Maximum amount that can be redeemed during an epoch\\n    uint256 public redeemLimit;\\n\\n    \/\/ Amount already redeemed during the \`currentEpoch\`\\n    uint256 internal _currentRedeemAmount;\\n\\n    \/\/ Decimal multiplier representing the difference between \`ULTRA\` decimals\\n    \/\/ In \`collateral\` token decimals\\n    uint256 internal _decimalsMultiplier;\\n\\n    bytes32 internal constant MINTER_ADMIN = keccak256(\\\"MINTER_ADMIN\\\");\\n    bytes32 internal constant OPERATOR_ADMIN = keccak256(\\\"OPERATOR_ADMIN\\\");\\n    bytes32 internal constant OFFCHAIN_SERVICE = keccak256(\\\"OFFCHAIN_SERVICE\\\");\\n\\n    \/\/ UNUSED VARIABLE\\n    address internal kycAddress;\\n\\n    \/\/ Variable that allows us to specify basis points in calculations, this was upgraded from a constant to a variable\\n    uint256 public BPS_DENOMINATOR;\\n\\n    mapping(uint256 =\u003e mapping(address =\u003e uint256)) internal _redemptionRequestsPerEpoch;\\n\\n    uint256 internal constant SECONDS_PER_DAY = 86_400;\\n\\n    \/\/\/ @notice Seconds past the epoch-period boundary (\`timestamp % _epochDuration == 0\`) at which this\\n    \/\/\/         fund\u0027s dealing cutoff falls — the position within every period where the epoch rolls and\\n    \/\/\/         mint\/redeem capacity resets. Always less than \`_epochDuration\`.\\n    uint256 public epochCutoffOffset;\\n\\n    \/\/\/ @notice Address permitted to consume and release this manager\u0027s per-epoch redeem\\n    \/\/\/         capacity on behalf of fiat redemptions (the UltraManagerFiat proxy).\\n    address public fiatManager;\\n\\n    \/\/\/ @custom:oz-upgrades-unsafe-allow constructor\\n    constructor() {\\n        _disableInitializers();\\n    }\\n\\n    \/**\\n     * @notice Initializes the UltraManager contract with core dependencies and configuration\\n     * @dev Sets up initial state including roles, contracts, and operational parameters\\n     * @param collateral Address of the ERC20 token used as collateral\\n     * @param ultra Address of the Ultra token contract\\n     * @param operatorAdmin Address that will receive the OPERATOR_ADMIN role\\n     * @param defaultAdmin Address that will receive the DEFAULT_ADMIN_ROLE\\n     * @param minterAdmin Address that will receive the MINTER_ADMIN role\\n     * @param offchainService Address that will receive the OFFCHAIN_SERVICE role\\n     * @param kyc Address of the KYC contract\\n     * @param assetRecipient Address that will receive deposited collateral\\n     * @param assetSender Address from which redemptions are processed\\n     * @param epochDuration Duration of each epoch in seconds\\n     * @param feeRecipient Address that will receive fees\\n     * @param _mintLimit Maximum amount that can be minted during an epoch\\n     * @param _redeemLimit Maximum amount that can be redeemed during an epoch\\n     * @param currentEpochStartTimestamp Timestamp when the first epoch starts\\n     * @param cutoffOffset Seconds past the epoch-period boundary for this fund\u0027s dealing cutoff\\n     *                     (see \`epochCutoffOffset\` for how the boundary depends on \`epochDuration\`)\\n     *\/\\n    function initialize(\\n        address collateral,\\n        address ultra,\\n        address operatorAdmin,\\n        address defaultAdmin,\\n        address minterAdmin,\\n        address offchainService,\\n        address kyc,\\n        address assetRecipient,\\n        address assetSender,\\n        uint256 epochDuration,\\n        address feeRecipient,\\n        uint256 _mintLimit,\\n        uint256 _redeemLimit,\\n        uint256 currentEpochStartTimestamp,\\n        uint256 cutoffOffset\\n    ) public initializer {\\n        __AccessControlEnumerable_init();\\n        __Pausable_init();\\n        __ReentrancyGuard_init();\\n        __UUPSUpgradeable_init();\\n\\n        _ultraManagerInitUnchained(\\n            collateral,\\n            ultra,\\n            operatorAdmin,\\n            defaultAdmin,\\n            minterAdmin,\\n            offchainService,\\n            kyc,\\n            assetRecipient,\\n            assetSender,\\n            epochDuration,\\n            feeRecipient,\\n            _mintLimit,\\n            _redeemLimit,\\n            currentEpochStartTimestamp,\\n            cutoffOffset\\n        );\\n    }\\n\\n    \/**\\n     * @notice One-time migration that seeds \`epochCutoffOffset\` and \`fiatManager\` on a proxy\\n     *         upgraded from an implementation that predates those variables. The cutoff is\\n     *         derived from the current epoch start; \`fiatManager\` is set from the argument.\\n     * @param fiatManagerAddress Address of the UltraManagerFiat proxy permitted to share redeem capacity\\n     *\/\\n    function initializeEpochCutoffOffset(address fiatManagerAddress)\\n        external\\n        reinitializer(2)\\n        onlyRole(DEFAULT_ADMIN_ROLE)\\n    {\\n        uint256 epochStart = _currentEpochStartTimestamp;\\n        require(epochStart != 0, \\\"EpochStartNotSet\\\");\\n        require(_epochDuration != 0, \\\"EpochDurationNotSet\\\");\\n\\n        \/\/ Set before the matching-offset early return so a healthy proxy still gets fiatManager.\\n        _setFiatManager(fiatManagerAddress);\\n\\n        uint256 derivedOffset = epochStart % _epochDuration;\\n        if (derivedOffset == epochCutoffOffset) {\\n            return;\\n        }\\n        _setEpochCutoffOffset(derivedOffset);\\n    }\\n\\n    \/**\\n     * @notice Performs the core initialization logic for the UltraManager contract\\n     * @dev Internal function called by initialize to set up the contract state\\n     * @param collateral Address of the ERC20 token used as collateral\\n     * @param ultra Address of the Ultra token contract\\n     * @param operatorAdmin Address that will receive the OPERATOR_ADMIN role\\n     * @param defaultAdmin Address that will receive the DEFAULT_ADMIN_ROLE\\n     * @param minterAdmin Address that will receive the MINTER_ADMIN role\\n     * @param offchainService Address that will receive the OFFCHAIN_SERVICE role\\n     * @param kyc Address of the KYC contract\\n     * @param assetRecipient Address that will receive deposited collateral\\n     * @param assetSender Address from which redemptions are processed\\n     * @param epochDuration Duration of each epoch in seconds\\n     * @param feeRecipient Address that will receive fees\\n     * @param _mintLimit Maximum amount that can be minted during an epoch\\n     * @param _redeemLimit Maximum amount that can be redeemed during an epoch\\n     * @param currentEpochStartTimestamp Timestamp when the first epoch starts\\n     * @param cutoffOffset Seconds past the epoch-period boundary for this fund\u0027s dealing cutoff\\n     *                     (see \`epochCutoffOffset\` for how the boundary depends on \`epochDuration\`)\\n     *\/\\n    function _ultraManagerInitUnchained(\\n        address collateral,\\n        address ultra,\\n        address operatorAdmin,\\n        address defaultAdmin,\\n        address minterAdmin,\\n        address offchainService,\\n        address kyc,\\n        address assetRecipient,\\n        address assetSender,\\n        uint256 epochDuration,\\n        address feeRecipient,\\n        uint256 _mintLimit,\\n        uint256 _redeemLimit,\\n        uint256 currentEpochStartTimestamp,\\n        uint256 cutoffOffset\\n    ) internal {\\n        require(collateral != address(0), \\\"CollateralZeroAddress\\\");\\n        require(ultra != address(0), \\\"UltraZeroAddress\\\");\\n        require(kyc != address(0), \\\"KycZeroAddress\\\");\\n        require(assetRecipient != address(0), \\\"AssetRecipientZeroAddress\\\");\\n        require(operatorAdmin != address(0), \\\"OperatorAdminZeroAddress\\\");\\n        require(defaultAdmin != address(0), \\\"DefaultAdminZeroAddress\\\");\\n        require(minterAdmin != address(0), \\\"MinterAdminZeroAddress\\\");\\n        require(offchainService != address(0), \\\"OffchainServiceZeroAddress\\\");\\n        require(feeRecipient != address(0), \\\"FeeRecipientZeroAddress\\\");\\n        if (currentEpochStartTimestamp \u003e block.timestamp) {\\n            revert EpochStartInFuture();\\n        }\\n        if (assetSender == address(0)) {\\n            assetSender = address(this);\\n        }\\n        _grantRole(DEFAULT_ADMIN_ROLE, defaultAdmin);\\n        _grantRole(OPERATOR_ADMIN, operatorAdmin);\\n        _grantRole(MINTER_ADMIN, minterAdmin);\\n        _grantRole(OFFCHAIN_SERVICE, offchainService);\\n\\n        _collateral = IERC20(collateral);\\n        _ultra = Ultra(ultra);\\n        kycAddress = kyc;\\n        _feeRecipient = feeRecipient;\\n        _assetRecipient = assetRecipient;\\n        _assetSender = assetSender;\\n\\n        mintLimit = _mintLimit;\\n        redeemLimit = _redeemLimit;\\n        _setEpochDuration(epochDuration);\\n        _setEpochCutoffOffset(cutoffOffset);\\n        BPS_DENOMINATOR = 1_000_000;\\n\\n        \/\/ Transitions step whole periods from this start, so a start off the cutoff position would\\n        \/\/ roll the fund at the wrong point in the period for its entire life.\\n        if (currentEpochStartTimestamp % _epochDuration != cutoffOffset) {\\n            revert EpochStartNotAlignedToCutoff();\\n        }\\n\\n        _currentEpochStartTimestamp = currentEpochStartTimestamp;\\n        _contractStartTimestamp = currentEpochStartTimestamp;\\n\\n        _decimalsMultiplier = 10 ** (IERC20Metadata(ultra).decimals() - IERC20Metadata(collateral).decimals());\\n\\n        minimumDepositAmount = 10_000_000_000;\\n        mintFee = 0;\\n        lastSetMintExchangeRate = 1e6;\\n        minimumRedeemAmountFiat = 50_000_000_000;\\n    }\\n\\n    function _authorizeUpgrade(address \/* newImplemenation *\/ ) internal view override {\\n        require(hasRole(DEFAULT_ADMIN_ROLE, msg.sender), \\\"UltraManager: unauthorized\\\");\\n    }\\n\\n    \/**\\n     * @notice Allows users to request the minting of ULTRA tokens in exchange for collateral.\\n     * Users send collateral to the contract, and ULTRA tokens will be minted after the promise is resolved by an admin\\n     *\\n     * @param collateralAmountIn Amount of collateral tokens to deposit.\\n     *\/\\n    function requestMint(uint256 collateralAmountIn)\\n        external\\n        override\\n        updateEpoch\\n        nonReentrant\\n        whenNotPaused\\n        checkKYC(msg.sender)\\n    {\\n        if (collateralAmountIn \u003c minimumDepositAmount) {\\n            revert MintRequestAmountTooSmall();\\n        }\\n\\n        \/\/ Fee is calculated for the event only; collection is deferred until resolveDeposit\\n        \/\/ so cancelled mint requests can refund the full deposited amount.\\n        uint256 feesInCollateral = _getMintFees(collateralAmountIn);\\n        uint256 depositValueAfterFees = collateralAmountIn - feesInCollateral;\\n\\n        _checkAndUpdateMintLimit(depositValueAfterFees);\\n\\n        _mintRequestsPerEpoch[currentEpoch][msg.sender] += collateralAmountIn;\\n\\n        bool success = _collateral.transferFrom(msg.sender, address(this), collateralAmountIn);\\n        require(success, \\\"Initial transfer failed\\\");\\n\\n        \/\/ Transfer the full deposit to the asset recipient; fee is collected on resolve\\n        success = _collateral.transfer(_assetRecipient, collateralAmountIn);\\n        require(success, \\\"Asset recipient transfer failed\\\");\\n\\n        emit MintRequested(msg.sender, currentEpoch, collateralAmountIn, depositValueAfterFees, feesInCollateral);\\n    }\\n\\n    \/**\\n     * @dev Pauses all contract activities that are marked as \`whenNotPaused\`.\\n     * This function can only be called by an account with the \`MANAGER_ADMIN\` role.\\n     * Once called, it sets the contract state to paused, preventing execution of functions that require the contract to be in a non-paused state.\\n     * This is useful for emergency stops or maintenance tasks.\\n     *\\n     * Requirements:\\n     * - The caller must have the \`MANAGER_ADMIN\` role.\\n     *\\n     * Emits a \`Paused\` event.\\n     *\/\\n    function pause() external onlyRole(OPERATOR_ADMIN) {\\n        _pause();\\n    }\\n\\n    \/**\\n     * @dev Unpauses the contract, resuming activities that are marked as \`whenNotPaused\`.\\n     * This function can only be called by an account with the \`MANAGER_ADMIN\` role.\\n     * It reverses the effect of the \`pause\` function, allowing normal operations of the contract functions that were previously halted.\\n     * This is typically used after the reason for the pause has been resolved.\\n     *\\n     * Requirements:\\n     * - The caller must have the \`MANAGER_ADMIN\` role.\\n     * - The contract must be in a paused state.\\n     *\\n     * Emits an \`Unpaused\` event.\\n     *\/\\n    function unpause() external onlyRole(OPERATOR_ADMIN) {\\n        _unpause();\\n    }\\n\\n    \/**\\n     * @notice Allows admin to resolve promise and send ULTRA tokens to an investor earned based on their deposited amount and the current Net Asset Value (NAV) of the fund.\\n     * The number of tokens minted is determined by dividing the deposited amount by the scaled NAV of the fund for that day (scaled by a factor of 1,000,000 for four decimal places).\\n     *\\n     * @param user Address of the user claiming the ULTRA tokens.\\n     * @param epochToClaim Epoch for which the user is claiming tokens\\n     * @param afterFeeAmount amount after fee\\n     *\/\\n    function resolveDeposit(address user, uint256 epochToClaim, uint256 afterFeeAmount)\\n        external\\n        updateEpoch\\n        whenNotPaused\\n        nonReentrant\\n        onlyRole(MINTER_ADMIN)\\n    {\\n        require(_epochToExchangeRate[epochToClaim] != 0, \\\"NAV not set for this epoch\\\");\\n\\n        \/\/ Process mint if user is not zero address\\n        require(user != address(0), \\\"Cannot resolve deposit for zero address\\\");\\n        _checkKYC(user);\\n        uint256 collateralDeposited = _mintRequestsPerEpoch[epochToClaim][user];\\n        require(collateralDeposited != 0, \\\"User has no remaining collateral deposited\\\");\\n\\n        \/\/ mintFee at resolve time determines the fee; afterFeeAmount may be below that net amount\\n        uint256 feesInCollateral = _getMintFees(collateralDeposited);\\n        uint256 expectedAfterFee = collateralDeposited - feesInCollateral;\\n        require(afterFeeAmount \u003c= expectedAfterFee, \\\"Collateral amount mismatch\\\");\\n\\n        _mintRequestsPerEpoch[epochToClaim][user] = 0;\\n\\n        if (feesInCollateral \u003e 0) {\\n            bool success;\\n            if (_assetSender == address(this)) {\\n                success = _collateral.transfer(_feeRecipient, feesInCollateral);\\n            } else {\\n                success = _collateral.transferFrom(_assetSender, _feeRecipient, feesInCollateral);\\n            }\\n            require(success, \\\"Fee transfer failed\\\");\\n        }\\n\\n        uint256 ultraOwed = (afterFeeAmount * BPS_DENOMINATOR) \/ _epochToExchangeRate[epochToClaim];\\n\\n        _ultra.mint(user, ultraOwed);\\n\\n        emit MintCompleted(\\n            user, ultraOwed, collateralDeposited, _epochToExchangeRate[epochToClaim], epochToClaim, msg.sender\\n        );\\n    }\\n\\n    \/**\\n     * @notice Allows admin to refund collateral to an investor by canceling their mint request.\\n     * The collateral amount is returned to the refundee\u0027s address based on their original deposit.\\n     *\\n     * @param refundee Address of the user to refund the collateral to.\\n     * @param epochToClaim Epoch for which the refund is being processed.\\n     *\/\\n    function refundDeposit(address refundee, uint256 epochToClaim)\\n        external\\n        updateEpoch\\n        whenNotPaused\\n        nonReentrant\\n        onlyRole(MINTER_ADMIN)\\n    {\\n        require(refundee != address(0), \\\"Refundee cannot be zero address\\\");\\n        _checkKYC(refundee);\\n        _processDepositRefund(refundee, epochToClaim);\\n    }\\n\\n    \/**\\n     * @dev Allows the owner to transfer out any ERC20 tokens hold in the contract\\n     * @param tokenAddress The address of the ERC20 token to transfer\\n     * @param to Address to transfer the tokens to\\n     * @param amount Amount of tokens to transfer\\n     *\/\\n    function transferCollateral(address tokenAddress, address to, uint256 amount)\\n        external\\n        onlyRole(OPERATOR_ADMIN)\\n        whenNotPaused\\n        nonReentrant\\n    {\\n        require(tokenAddress != address(0), \\\"TokenZeroAddress\\\");\\n        require(to != address(0), \\\"MyContract: transfer to the zero address\\\");\\n        IERC20(tokenAddress).safeTransfer(to, amount);\\n        emit CollateralTransfered(tokenAddress, to, amount, msg.sender);\\n    }\\n\\n    \/**\\n     * @dev Processes refund of deposit for a specified epoch.\\n     * This is a private function that calculates and transfers the refund amount in ULTRA tokens to the provided address.\\n     * If the contract doesn\u0027t have sufficient collateral balance to fulfill the refund, it reverts the state.\\n     * @param refundee The address to whom the refund will be issued.\\n     * @param epochToService The epoch for which the refund is being processed.\\n     *\\n     * @return totalUltraAmountRefunded The amount of ULTRA tokens refunded in this transaction.\\n     *\\n     * Requirements:\\n     * - The function requires that the contract has enough collateral balance to cover the refund.\\n     * - The function emits \`DepositRefundIssued\` event for successful refund or \`DepositRefundWithoutCollateral\` event if refund cannot be processed due to insufficient collateral.\\n     *\/\\n    function _processDepositRefund(address refundee, uint256 epochToService)\\n        private\\n        returns (uint256 totalUltraAmountRefunded)\\n    {\\n        \/\/ Skip refund processing if refundee is zero address\\n        require(refundee != address(0), \\\"Refundee cannot be zero address\\\");\\n\\n        uint256 collateralRefund = _mintRequestsPerEpoch[epochToService][refundee];\\n        _mintRequestsPerEpoch[epochToService][refundee] = 0;\\n\\n        _currentMintAmount = _releaseEpochCapacity(_currentMintAmount, collateralRefund, epochToService, currentEpoch);\\n\\n        uint256 collateralBalance = _collateral.balanceOf(_assetSender);\\n\\n        require(collateralBalance \u003e= collateralRefund, \\\"Insufficient collateral to complete refund\\\");\\n\\n        require(collateralRefund \u003c= _collateral.balanceOf(_assetSender), \\\"Insufficient token balance\\\");\\n\\n        bool success;\\n        if (_assetSender == address(this)) {\\n            success = _collateral.transfer(refundee, collateralRefund);\\n        } else {\\n            success = _collateral.transferFrom(_assetSender, refundee, collateralRefund);\\n        }\\n        require(success, \\\"Transfer failed\\\");\\n\\n        totalUltraAmountRefunded = collateralRefund;\\n        emit DepositRefundIssued(refundee, collateralRefund, epochToService, msg.sender);\\n        return totalUltraAmountRefunded;\\n    }\\n\\n    \/**\\n     * @notice Creates a transfer promise to move tokens from one address to another.\\n     *\\n     * This function records a promise to transfer a specified amount of tokens from the \`from\` address to the \`to\` address.\\n     * It is restricted to being called only by the Ultra contract. On successful execution, it emits a \`TransferPromiseCreated\` event.\\n     * Reverts when the manager is paused so over-limit Ultra transfers cannot escrow new promises during a pause.\\n     *\\n     * @param from The address from which the tokens are promised to be transferred.\\n     * @param to The address to receive the tokens.\\n     * @param amount The amount of tokens to be transferred.\\n     * @return True if the transfer promise is successfully created.\\n     *\\n     * Emits a \`TransferPromiseCreated\` event.\\n     *\/\\n    function createTransferPromise(address from, address to, uint256 amount) external whenNotPaused returns (bool) {\\n        require(msg.sender == address(_ultra), \\\"UltraManager: Unauthorized call\\\"); \/\/ Ensure only Ultra contract can call this\\n        require(from != address(0), \\\"FromZeroAddress\\\");\\n        require(to != address(0), \\\"ToZeroAddress\\\");\\n\\n        transferPromises[from][to] += amount;\\n\\n        emit TransferPromiseCreated(from, to, amount); \/\/ Emit the event\\n        return true;\\n    }\\n\\n    \/**\\n     * @notice Fulfills a previously made transfer promise by transferring the specified amount of tokens.\\n     *\\n     * This external function is responsible for fulfilling a transfer promise. It checks if the promised amount\\n     * between the \`from\` and \`to\` addresses is sufficient and then proceeds to transfer the specified \`amount\` of tokens.\\n     * Access to this function is restricted to accounts with the \`OFFCHAIN_SERVICE\` role. It is also marked as \`nonReentrant\` for added security.\\n     *\\n     * @param from The address from which the promised tokens are transferred.\\n     * @param to The address to receive the tokens.\\n     * @param amount The amount of tokens to be transferred.\\n     *\\n     * Requirements:\\n     * - The caller must have the \`MINTER_ADMIN\` role.\\n     * - The promised amount must be equal to or greater than the specified \`amount\`.\\n     *\\n     * Emits a \`TransferPromiseFulfilled\` event on successful transfer.\\n     *\/\\n    function fulfillTransferPromise(address from, address to, uint256 amount)\\n        external\\n        onlyRole(MINTER_ADMIN)\\n        whenNotPaused\\n        nonReentrant\\n    {\\n        require(from != address(0), \\\"FromZeroAddress\\\");\\n        require(to != address(0), \\\"ToZeroAddress\\\");\\n        uint256 promisedAmount = transferPromises[from][to];\\n        require(promisedAmount \u003e= amount, \\\"UltraManager: Amount exceeds promise\\\");\\n\\n        transferPromises[from][to] -= amount; \/\/ Reduce the amount of tokens promised\\n\\n        \/\/ Transfer the tokens to the recipient\\n        _ultra.completeTransfer(to, amount);\\n\\n        emit TransferPromiseFulfilled(from, to, amount);\\n    }\\n\\n    \/**\\n     * @notice Refunds a transfer promise by sending the promised ULTRA back to the initial holder.\\n     * @param from The address that initially promised to transfer ULTRA.\\n     * @param to The address that was supposed to receive the ULTRA.\\n     * @param amount The amount of ULTRA tokens to refund.\\n     *\/\\n    function refundTransferPromise(address from, address to, uint256 amount)\\n        external\\n        onlyRole(OFFCHAIN_SERVICE)\\n        whenNotPaused\\n        nonReentrant\\n    {\\n        require(from != address(0), \\\"FromZeroAddress\\\");\\n        require(to != address(0), \\\"ToZeroAddress\\\");\\n        uint256 promisedAmount = transferPromises[from][to];\\n        require(promisedAmount \u003e= amount, \\\"UltraManager: Amount exceeds promise\\\");\\n\\n        transferPromises[from][to] -= amount; \/\/ Reduce the amount of tokens promised\\n\\n        \/\/ Transfer the tokens back to the initial holder\\n        _ultra.completeTransfer(from, amount);\\n\\n        emit TransferPromiseRefunded(from, to, amount);\\n    }\\n\\n    \/**\\n     * @notice Computes the minting fee for a given collateral amount.\\n     *\\n     * @param collateralAmount Amount of collateral deposited.\\n     * @return The calculated minting fee.\\n     *\/\\n    function _getMintFees(uint256 collateralAmount) private view returns (uint256) {\\n        return (collateralAmount * mintFee) \/ BPS_DENOMINATOR;\\n    }\\n\\n    \/**\\n     * @notice Checks and updates the current mint limit.\\n     * Ensures that mint operations do not exceed the set rate limit.\\n     *\\n     * @param collateralAmountIn Amount of collateral deposited for minting.\\n     *\/\\n    function _checkAndUpdateMintLimit(uint256 collateralAmountIn) private {\\n        uint256 remaining = mintLimit \u003e _currentMintAmount ? mintLimit - _currentMintAmount : 0;\\n        if (collateralAmountIn \u003e remaining) {\\n            revert MintExceedsRateLimit();\\n        }\\n\\n        _currentMintAmount += collateralAmountIn;\\n    }\\n\\n    \/**\\n     * @notice Sets the minimum amount of collateral that can be deposited.\\n     * @dev Can only be called by an account with the \`MANAGER_ADMIN\` role.\\n     *\\n     * @param newMinimumDepositAmount The minimum amount of collateral to set.\\n     *\/\\n    function setMinimumDepositAmount(uint256 newMinimumDepositAmount) external override onlyRole(OPERATOR_ADMIN) {\\n        if (newMinimumDepositAmount \u003c BPS_DENOMINATOR) {\\n            revert MinimumDepositAmountTooSmall();\\n        }\\n        uint256 oldMinimumDepositAmount = minimumDepositAmount;\\n        minimumDepositAmount = newMinimumDepositAmount;\\n        emit MinimumDepositAmountSet(oldMinimumDepositAmount, minimumDepositAmount);\\n    }\\n\\n    \/**\\n     * @notice Sets the exchange rate for a given epoch.\\n     * @dev Can only be called by an account with the \`MINTER_ADMIN\` role.\\n     *\\n     * @param navScaled The Net Asset Value (NAV) of the fund per Ultra token for the day, scaled appropriately (e.g., scaled by a factor of 10000 for 4 decimal places).\\n     * This represents the value of one share in the fund or pool in scaled units.\\n     * @param epochsToSet The epoch for which the exchange rate is being set.\\n     *\\n     *\/\\n    function setNavForMultipleEpochs(uint256 navScaled, uint256[] memory epochsToSet)\\n        external\\n        override\\n        updateEpoch\\n        onlyRole(MINTER_ADMIN)\\n    {\\n        require(navScaled != 0, \\\"ZeroExchangeRate\\\");\\n\\n        for (uint256 i = 0; i \u003c epochsToSet.length; i++) {\\n            uint256 epochToSet = epochsToSet[i];\\n            if (epochToSet \u003e currentEpoch) {\\n                revert MustServicePastEpoch();\\n            }\\n            uint256 oldExchangeRate = lastSetMintExchangeRate;\\n            _epochToExchangeRate[epochToSet] = navScaled;\\n\\n            emit MintExchangeRateSet(epochToSet, oldExchangeRate, navScaled);\\n        }\\n\\n        \/\/ Scan down through epoch 0; stop before uint256 underflow on i--.\\n        for (uint256 i = currentEpoch;; i--) {\\n            if (_epochToExchangeRate[i] != 0) {\\n                lastSetMintExchangeRate = _epochToExchangeRate[i];\\n                break;\\n            }\\n            if (i == 0) break;\\n        }\\n    }\\n\\n    \/**\\n     * @notice Overrides the exchange rate for a given epoch.\\n     * @dev Can only be called by an account with the \`MINTER_ADMIN\` role.\\n     *\\n     * @param correctExchangeRate The corrected exchange rate.\\n     * @param epochToSet The epoch for which the exchange rate is being overridden.\\n     * @param _lastSetMintExchangeRate The last set mint exchange rate.\\n     *\/\\n    function overrideExchangeRate(uint256 correctExchangeRate, uint256 epochToSet, uint256 _lastSetMintExchangeRate)\\n        external\\n        override\\n        updateEpoch\\n        onlyRole(MINTER_ADMIN)\\n    {\\n        require(correctExchangeRate != 0, \\\"ZeroExchangeRate\\\");\\n        if (epochToSet \u003e currentEpoch) {\\n            revert MustServicePastEpoch();\\n        }\\n        uint256 incorrectRate = _epochToExchangeRate[epochToSet];\\n        _epochToExchangeRate[epochToSet] = correctExchangeRate;\\n        if (_lastSetMintExchangeRate != 0) {\\n            lastSetMintExchangeRate = _lastSetMintExchangeRate;\\n        }\\n        emit MintExchangeRateOverridden(epochToSet, incorrectRate, correctExchangeRate, lastSetMintExchangeRate);\\n    }\\n\\n    \/**\\n     * @notice Allows a user to request redemption of tokens.\\n     * @dev Ensures user is KYC approved and contract is not paused.\\n     * @param amountUltraToRedeem Amount of tokens to redeem.\\n     * @param fullWithdrawal If true, redeem entire balance\\n     *\/\\n    function requestRedemption(uint256 amountUltraToRedeem, bool fullWithdrawal)\\n        external\\n        updateEpoch\\n        nonReentrant\\n        whenNotPaused\\n        checkKYC(msg.sender)\\n    {\\n        uint256 amountToRedeem;\\n        \/\/ If full withdrawal is true, use entire balance regardless of amountUltraToRedeem parameter\\n        if (fullWithdrawal) {\\n            amountToRedeem = _ultra.balanceOf(msg.sender);\\n            require(amountToRedeem \u003e 0, \\\"No Ultra tokens to redeem\\\");\\n        } else {\\n            \/\/ Calculate fiat value of redemption request\\n            uint256 fiatValue = (amountUltraToRedeem * lastSetMintExchangeRate) \/ BPS_DENOMINATOR;\\n\\n            \/\/ Check if the fiat value meets the minimum requirement\\n            require(fiatValue \u003e= minimumRedeemAmountFiat, \\\"Fiat value below minimum\\\");\\n            amountToRedeem = amountUltraToRedeem;\\n        }\\n        _checkAndUpdateRedeemLimit(amountToRedeem);\\n\\n        \/\/ Check if user already has a redemption request for current epoch\\n        uint256 existingRequest = _redemptionRequestsPerEpoch[currentEpoch][msg.sender];\\n        if (existingRequest \u003e 0) {\\n            \/\/ Update existing request by adding new amount\\n            _redemptionRequestsPerEpoch[currentEpoch][msg.sender] = existingRequest + amountToRedeem;\\n        } else {\\n            \/\/ Create new request\\n            _redemptionRequestsPerEpoch[currentEpoch][msg.sender] = amountToRedeem;\\n        }\\n\\n        require(_ultra.transferFromManager(msg.sender, address(this), amountToRedeem), \\\"Token transfer failed\\\");\\n\\n        emit RedemptionRequested(msg.sender, amountToRedeem, currentEpoch);\\n    }\\n\\n    \/**\\n     * @notice Processes redemption request for a specific epoch.\\n     * @param redeemer The address of redeemer whose redemption request is to be processed.\\n     * @param epochToClaim The epoch for which the redemption is being processed.\\n     *\/\\n    function completeRedemptions(address redeemer, uint256 epochToClaim, uint256 collateralAmountAfterFee)\\n        external\\n        onlyRole(MINTER_ADMIN)\\n        whenNotPaused\\n    {\\n        require(redeemer != address(0), \\\"RedeemerZeroAddress\\\");\\n        require(_epochToExchangeRate[epochToClaim] != 0, \\\"NAV not set for this epoch\\\");\\n\\n        uint256 ultraAmountRequested = _redemptionRequestsPerEpoch[epochToClaim][redeemer];\\n        require(ultraAmountRequested \u003e 0, \\\"No redemption request found\\\");\\n        require(_isKYCValid(redeemer), \\\"Redeemer KYC not valid\\\");\\n\\n        uint256 exchangeRate = _epochToExchangeRate[epochToClaim];\\n        uint256 ultraAmountRequestedValue = (ultraAmountRequested * exchangeRate) \/ BPS_DENOMINATOR; \/\/ convert requested ULTRA amount to USD value\\n        require(\\n            ultraAmountRequestedValue \u003e= collateralAmountAfterFee,\\n            \\\"Calculated redemption value is less than collateralAmountAfterFee\\\"\\n        );\\n\\n        require(collateralAmountAfterFee \u003e 0, \\\"Invalid collateral amount\\\");\\n        require(collateralAmountAfterFee \u003c= _collateral.balanceOf(_assetSender), \\\"Insufficient token balance\\\");\\n\\n        \/\/ Clear the redemption request\\n        _redemptionRequestsPerEpoch[epochToClaim][redeemer] = 0;\\n\\n        \/\/ Burn ULTRA tokens\\n        _ultra.burn(ultraAmountRequested);\\n\\n        \/\/ Transfer collateral\\n        bool success;\\n        if (_assetSender == address(this)) {\\n            success = _collateral.transfer(redeemer, collateralAmountAfterFee);\\n        } else {\\n            success = _collateral.transferFrom(_assetSender, redeemer, collateralAmountAfterFee);\\n        }\\n        require(success, \\\"Collateral transfer failed\\\");\\n\\n        emit RedemptionCompleted(redeemer, ultraAmountRequested, collateralAmountAfterFee, epochToClaim);\\n    }\\n\\n    \/**\\n     * @notice Refunds a redemption request.\\n     * @param refundee The address to refund the ULTRA tokens to.\\n     * @param epochToRefund The epoch for which to refund the redemption.\\n     *\/\\n    function refundRedemptions(address refundee, uint256 epochToRefund)\\n        external\\n        onlyRole(MINTER_ADMIN)\\n        whenNotPaused\\n        nonReentrant\\n    {\\n        require(refundee != address(0), \\\"Refundee cannot be zero address\\\");\\n        require(_isKYCValid(refundee), \\\"Refundee KYC not valid\\\");\\n\\n        uint256 ultraAmount = _redemptionRequestsPerEpoch[epochToRefund][refundee];\\n        require(ultraAmount \u003e 0, \\\"No redemption request found\\\");\\n\\n        \/\/ Clear the redemption request\\n        _redemptionRequestsPerEpoch[epochToRefund][refundee] = 0;\\n\\n        _currentRedeemAmount = _releaseEpochCapacity(_currentRedeemAmount, ultraAmount, epochToRefund, currentEpoch);\\n\\n        \/\/ Return ULTRA tokens to refundee\\n        _ultra.completeTransfer(refundee, ultraAmount);\\n\\n        emit RedemptionRefunded(refundee, ultraAmount, epochToRefund);\\n    }\\n\\n    \/**\\n     * @notice Checks and updates the current redeem limit.\\n     * @dev Callable only by \`fiatManager\` (UltraManagerFiat) so fiat redemptions share the same per-epoch cap.\\n     * @param amount The amount to be redeemed.\\n     *\/\\n    function checkAndUpdateRedeemLimit(uint256 amount) external onlyFiatManager {\\n        _checkAndUpdateRedeemLimit(amount);\\n    }\\n\\n    \/**\\n     * @notice Checks and updates the current redeem limit.\\n     * @param amount The amount to be redeemed.\\n     *\/\\n    function _checkAndUpdateRedeemLimit(uint256 amount) private {\\n        require(amount \u003e 0, \\\"RedeemAmountCannotBeZero\\\");\\n        uint256 remaining = redeemLimit \u003e _currentRedeemAmount ? redeemLimit - _currentRedeemAmount : 0;\\n        if (amount \u003e remaining) {\\n            revert RedeemExceedsRateLimit();\\n        }\\n        _currentRedeemAmount += amount;\\n    }\\n\\n    \/**\\n     * @notice Releases previously-consumed epoch capacity, clamped to zero.\\n     * @dev Returns \`counter\` unchanged if \`epoch\` isn\u0027t the active epoch or \`amount\` is zero,\\n     *      since capacity consumed in a past epoch has already been reset by \`_transitionEpoch\`.\\n     * @param counter The current value of the epoch counter (\`_currentMintAmount\` or \`_currentRedeemAmount\`).\\n     * @param amount The amount to release back to the epoch\u0027s capacity.\\n     * @param epoch The epoch the refunded request belonged to.\\n     * @param activeEpoch The current epoch (\`currentEpoch\`).\\n     * @return The new counter value.\\n     *\/\\n    function _releaseEpochCapacity(uint256 counter, uint256 amount, uint256 epoch, uint256 activeEpoch)\\n        private\\n        pure\\n        returns (uint256)\\n    {\\n        if (epoch != activeEpoch || amount == 0) {\\n            return counter;\\n        }\\n        return amount \u003e= counter ? 0 : counter - amount;\\n    }\\n\\n    \/**\\n     * @notice Reduces the current epoch\u0027s redeem counter when a fiat redemption is refunded.\\n     * @dev Callable only by \`fiatManager\` (UltraManagerFiat) so fiat refunds free the\\n     *      same per-epoch cap they consumed via \`checkAndUpdateRedeemLimit\`.\\n     * @param amount The amount to release back to the current epoch\u0027s redeem capacity.\\n     * @param epoch The epoch the refunded request belonged to.\\n     *\/\\n    function reduceCurrentRedeemAmount(uint256 amount, uint256 epoch) external onlyFiatManager {\\n        _currentRedeemAmount = _releaseEpochCapacity(_currentRedeemAmount, amount, epoch, currentEpoch);\\n    }\\n\\n    \/**\\n     * @notice Sets a new mint limit for the contract.\\n     *\\n     * This external function allows updating the mint limit, which is the maximum amount of tokens that can be minted.\\n     * Only an account with the \`OPERATOR_ADMIN\` role can execute this function.\\n     * It records the old mint limit before updating to the new value and emits a \`MintLimitSet\` event after the update.\\n     *\\n     * @param _mintLimit The new mint limit to be set.\\n     *\\n     * Requirements:\\n     * - The caller must have the \`OPERATOR_ADMIN\` role.\\n     *\\n     * Emits a \`MintLimitSet\` event indicating the old and new mint limits.\\n     *\/\\n    function setMintLimit(uint256 _mintLimit) external onlyRole(OPERATOR_ADMIN) {\\n        uint256 oldMintLimit = mintLimit;\\n        mintLimit = _mintLimit;\\n        emit MintLimitSet(oldMintLimit, mintLimit);\\n    }\\n\\n    \/**\\n     * @notice Updates the redeem limit of the contract.\\n     *\\n     * This external function allows the modification of the redeem limit, which is the maximum amount of tokens that can be redeemed.\\n     * It is accessible only by an account with the \`OPERATOR_ADMIN\` role.\\n     * The function saves the previous redeem limit, updates it to the new value, and then emits a \`RedeemLimitSet\` event to record this change.\\n     *\\n     * @param _redeemLimit The new redeem limit to be set.\\n     *\\n     * Requirements:\\n     * - The caller must have the \`OPERATOR_ADMIN\` role.\\n     *\\n     * Emits a \`RedeemLimitSet\` event indicating the old and new redeem limits.\\n     *\/\\n    function setRedeemLimit(uint256 _redeemLimit) external onlyRole(OPERATOR_ADMIN) {\\n        uint256 oldRedeemLimit = redeemLimit;\\n        redeemLimit = _redeemLimit;\\n        emit RedeemLimitSet(oldRedeemLimit, redeemLimit);\\n    }\\n\\n    \/**\\n     * @notice Checks if the KYC (Know Your Customer) status for a given account is valid.\\n     *\\n     * This private view function queries the KYC status of an account by calling the \`isKYC\` function on the KYC contract from the Ultra token contract.\\n     * It returns a boolean indicating whether the account has a valid KYC status.\\n     *\\n     * @param account The address of the account to check for KYC validity.\\n     * @return True if the account has a valid KYC status, false otherwise.\\n     *\/\\n    function _isKYCValid(address account) private view returns (bool) {\\n        \/\/ Skip KYC checks if KYC contract is not set (zero address)\\n        address ultraKycAddress = address(_ultra.KYCContract());\\n        if (ultraKycAddress == address(0)) {\\n            return true;\\n        }\\n        return KYCUltra(ultraKycAddress).isKYC(account);\\n    }\\n\\n    \/**\\n     * @notice Sets the asset sender address.\\n     * @dev Can only be called by an account with the \`OPERATOR_ADMIN\` role.\\n     *\\n     * @param newAssetSender The new asset sender address.\\n     *\/\\n    function setAssetSender(address newAssetSender) external onlyRole(OPERATOR_ADMIN) {\\n        require(newAssetSender != address(0), \\\"UltraManager: newAssetSender is the zero address\\\");\\n        address oldAssetSender = _assetSender;\\n        _assetSender = newAssetSender;\\n        emit AssetSenderSet(oldAssetSender, newAssetSender);\\n    }\\n\\n    \/**\\n     * @notice Sets the asset recipient address.\\n     * @dev Can only be called by an account with the \`OPERATOR_ADMIN\` role.\\n     *\\n     * @param newAssetRecipient The new asset recipient address.\\n     *\/\\n    function setAssetRecipient(address newAssetRecipient) external onlyRole(OPERATOR_ADMIN) {\\n        require(newAssetRecipient != address(0), \\\"UltraManager: newAssetRecipient is the zero address\\\");\\n        address oldAssetRecipient = _assetRecipient;\\n        _assetRecipient = newAssetRecipient;\\n        emit AssetRecipientSet(oldAssetRecipient, newAssetRecipient);\\n    }\\n\\n    \/**\\n     * @notice Sets the fee recipient address.\\n     * @dev Can only be called by an account with the \`OPERATOR_ADMIN\` role.\\n     *\\n     * @param newFeeRecipient The new fee recipient address.\\n     *\/\\n    function setFeeRecipient(address newFeeRecipient) external onlyRole(OPERATOR_ADMIN) {\\n        require(newFeeRecipient != address(0), \\\"UltraManager: newFeeRecipient is the zero address\\\");\\n        address oldFeeRecipient = _feeRecipient;\\n        _feeRecipient = newFeeRecipient;\\n        emit FeeRecipientSet(oldFeeRecipient, newFeeRecipient);\\n    }\\n\\n    \/**\\n     * @notice Sets the minimum redeem amount.\\n     * @dev Can only be called by an account with the \`OPERATOR_ADMIN\` role.\\n     *\\n     * @param newMinimumFiat The new minimum redeem amount.\\n     *\/\\n    function setMinimumRedeemAmountFiat(uint256 newMinimumFiat) external onlyRole(OPERATOR_ADMIN) {\\n        uint256 oldMinimumFiat = minimumRedeemAmountFiat;\\n        minimumRedeemAmountFiat = newMinimumFiat;\\n        emit MinimumRedeemAmountFiatSet(oldMinimumFiat, minimumRedeemAmountFiat);\\n    }\\n\\n    \/**\\n     * @notice Verifies if an account has passed the KYC (Know Your Customer) check.\\n     *\\n     * This private view function checks the KYC status of a given account using the \`isKYC\` function on the KYC contract from the Ultra token contract.\\n     * If the account has not passed the KYC check, the function reverts with a \`KYCNotApproved\` error.\\n     *\\n     * @param account The address of the account to check for KYC approval.\\n     *\\n     * Reverts:\\n     * - If the account has not passed the KYC check.\\n     *\/\\n    function _checkKYC(address account) private view {\\n        \/\/ Skip KYC checks if KYC contract is not set (zero address)\\n        address ultraKycAddress = address(_ultra.KYCContract());\\n        if (ultraKycAddress == address(0)) {\\n            return;\\n        }\\n        if (!KYCUltra(ultraKycAddress).isKYC(account)) {\\n            revert KYCNotApproved();\\n        }\\n    }\\n\\n    \/**\\n     * @notice Sets the duration of an epoch.\\n     * @dev Can only be called by an account with the \`OPERATOR_ADMIN\` role.\\n     *\\n     * @param epochDuration The new duration of an epoch.\\n     *\/\\n    function setEpochDuration(uint256 epochDuration) external onlyRole(OPERATOR_ADMIN) {\\n        _setEpochDuration(epochDuration);\\n    }\\n\\n    \/**\\n     * @dev Validates and stores the epoch duration. Must be positive and a whole-day multiple —\\n     *      86_400 for a daily fund, 604_800 for a weekly one — so the cutoff keeps a fixed position\\n     *      within the period. \`epochCutoffOffset\` is measured against this duration, so it must\\n     *      still fit inside the new period.\\n     *\\n     *      WARNING: changing the duration on a live fund re-anchors the cutoff grid (a stored offset\\n     *      of 1800 means 00:30 UTC daily but Thursday 00:30 UTC weekly) and can leave\\n     *      \`_currentEpochStartTimestamp\` off the new grid. Pair any duration change with a\\n     *      deliberate cutoff re-set.\\n     * @param epochDuration New epoch duration in seconds.\\n     *\/\\n    function _setEpochDuration(uint256 epochDuration) private {\\n        require(epochDuration \u003e 0, \\\"Epoch must be positive\\\");\\n        require(epochDuration % SECONDS_PER_DAY == 0, \\\"Epoch must be in multiples of days\\\");\\n        require(epochCutoffOffset \u003c epochDuration, \\\"Cutoff offset exceeds epoch duration\\\");\\n        uint256 oldEpochDuration = _epochDuration;\\n        _epochDuration = epochDuration;\\n        emit EpochDurationSet(oldEpochDuration, _epochDuration);\\n    }\\n\\n    \/**\\n     * @dev Validates and stores the epoch cutoff offset. Must fall inside one epoch period.\\n     * @param cutoffOffset New cutoff offset in seconds past the epoch-period boundary.\\n     *\/\\n    function _setEpochCutoffOffset(uint256 cutoffOffset) internal {\\n        if (cutoffOffset \u003e= _epochDuration) {\\n            revert InvalidEpochCutoffOffset();\\n        }\\n        uint256 oldOffset = epochCutoffOffset;\\n        epochCutoffOffset = cutoffOffset;\\n        emit EpochCutoffOffsetSet(oldOffset, epochCutoffOffset, currentEpoch);\\n    }\\n\\n    \/**\\n     * @dev Advances the epoch counter, resets mint\/redeem capacity, and emits \`EpochTransitionV2\`.\\n     * @param epochDelta Number of epochs to advance.\\n     * @param newStart Start timestamp for the newly opened epoch.\\n     *\/\\n    function _advanceEpoch(uint256 epochDelta, uint256 newStart) internal {\\n        uint256 prevEpoch = currentEpoch;\\n        _currentRedeemAmount = 0;\\n        _currentMintAmount = 0;\\n        currentEpoch = prevEpoch + epochDelta;\\n        _currentEpochStartTimestamp = newStart;\\n        emit EpochTransitionV2(prevEpoch, currentEpoch, newStart);\\n    }\\n\\n    \/**\\n     * @notice Transition to the next epoch if the current epoch\u0027s cutoff has passed.\\n     * @dev The boundary is \`_currentEpochStartTimestamp + _epochDuration\`, and skipped epochs are\\n     *      caught up in \`_epochDuration\` steps from the open start.\\n     *\/\\n    function _transitionEpoch() internal virtual {\\n        uint256 epochStart = _currentEpochStartTimestamp;\\n\\n        uint256 extraEpochs = (block.timestamp - epochStart) \/ _epochDuration;\\n        if (extraEpochs \u003e 0) {\\n            _advanceEpoch(extraEpochs, epochStart + extraEpochs * _epochDuration);\\n        }\\n    }\\n\\n    \/**\\n     * @notice Transition to the next epoch if the duration for the current epoch has passed.\\n     *\/\\n    function transitionEpochExternal() external override onlyRole(OFFCHAIN_SERVICE) {\\n        _transitionEpoch();\\n    }\\n\\n    \/**\\n     * @notice Sets the fee for the minting process.\\n     *\\n     * @param _mintFee The fee value to set for minting.\\n     *\/\\n    function setMintFee(uint256 _mintFee) external override onlyRole(OPERATOR_ADMIN) {\\n        require(_mintFee \u003c BPS_DENOMINATOR, \\\"Mint fee exceeds BPS\\\");\\n\\n        uint256 oldMintFee = mintFee;\\n        mintFee = _mintFee;\\n        emit MintFeeSet(oldMintFee, mintFee);\\n    }\\n\\n    \/**\\n     * @notice Gets contract start timestamp\\n     *\\n     * @return The contract start timestamp\\n     *\/\\n    function getContractStartTimestamp() external view override returns (uint256) {\\n        return _contractStartTimestamp;\\n    }\\n\\n    \/**\\n     * @notice Returns the timestamp when the current epoch started.\\n     * @return The start timestamp of \`currentEpoch\`.\\n     *\/\\n    function getCurrentEpochStartTimestamp() external view returns (uint256) {\\n        return _currentEpochStartTimestamp;\\n    }\\n\\n    \/**\\n     * @notice Returns the length of an epoch in seconds.\\n     * @dev \`epochCutoffOffset\` is measured against this, so off-chain verification of the cutoff\\n     *      needs both values: the same offset means a different wall-clock cutoff under a weekly\\n     *      duration than under a daily one.\\n     * @return The current \`_epochDuration\`.\\n     *\/\\n    function getEpochDuration() external view returns (uint256) {\\n        return _epochDuration;\\n    }\\n\\n    \/**\\n     * @notice Returns the timestamp at which a scheduled cutoff change first takes effect.\\n     * @return Always 0 — this implementation never schedules a cutoff change.\\n     *\/\\n    function getPendingNextEpochStart() external view virtual returns (uint256) {\\n        return 0;\\n    }\\n\\n    \/**\\n     * @dev Ensures that the epoch is up-to-date before executing a function.\\n     *\/\\n    modifier updateEpoch() {\\n        _transitionEpoch();\\n        _;\\n    }\\n\\n    \/**\\n     * @dev Ensures that an account has passed KYC before executing a function.\\n     *\\n     * @param account The address to check for KYC.\\n     *\/\\n    modifier checkKYC(address account) {\\n        _checkKYC(account);\\n        _;\\n    }\\n\\n    \/**\\n     * @dev Restricts a function to the configured \`fiatManager\` address.\\n     * An unset (zero) \`fiatManager\` rejects every caller, since \`msg.sender\` is never the zero address.\\n     *\/\\n    modifier onlyFiatManager() {\\n        if (msg.sender != fiatManager) {\\n            revert UnauthorizedFiatManager();\\n        }\\n        _;\\n    }\\n\\n    \/**\\n     * @notice Updates the Ultra token contract address\\n     * @dev Can only be called by an account with the OPERATOR_ADMIN role\\n     * @param ultra The address of the new Ultra token contract\\n     *\/\\n    function setUltraContract(address ultra) external onlyRole(OPERATOR_ADMIN) {\\n        require(ultra != address(0), \\\"UltraZeroAddress\\\");\\n        address oldUltra = address(_ultra);\\n        _ultra = Ultra(ultra);\\n        emit UltraContractSet(oldUltra, ultra);\\n    }\\n\\n    \/**\\n     * @notice Sets the address allowed to consume and release this manager\u0027s per-epoch redeem capacity\\n     * @dev Can only be called by an account with the OPERATOR_ADMIN role. Expected to be the UltraManagerFiat proxy.\\n     * @param newFiatManager The address of the fiat manager contract\\n     *\/\\n    function setFiatManager(address newFiatManager) external onlyRole(OPERATOR_ADMIN) {\\n        _setFiatManager(newFiatManager);\\n    }\\n\\n    \/**\\n     * @dev Validates and stores \`fiatManager\`. Rejects the zero address.\\n     * @param fiatManagerAddress The UltraManagerFiat proxy (or other permitted caller).\\n     *\/\\n    function _setFiatManager(address fiatManagerAddress) internal {\\n        require(fiatManagerAddress != address(0), \\\"FiatManagerZeroAddress\\\");\\n        address oldFiatManager = fiatManager;\\n        fiatManager = fiatManagerAddress;\\n        emit FiatManagerSet(oldFiatManager, fiatManagerAddress);\\n    }\\n\\n    \/**\\n     * @notice Sets the BPS denominator used for calculations\\n     * @dev Can only be called by an account with the OPERATOR_ADMIN role\\n     * @param newDenominator The new BPS denominator value to set\\n     *\/\\n    function setBPSDenominator(uint256 newDenominator) external onlyRole(OPERATOR_ADMIN) {\\n        require(newDenominator \u003e 0, \\\"Denominator must be greater than 0\\\");\\n        require(newDenominator \u003e mintFee, \\\"New denominator invalidates current fee percentage\\\");\\n        uint256 oldDenominator = BPS_DENOMINATOR;\\n        BPS_DENOMINATOR = newDenominator;\\n        emit BPSDenominatorSet(oldDenominator, newDenominator);\\n    }\\n\\n    function getTotalAndProcessingCount()\\n        external\\n        view\\n        returns (uint256 erc20Balance, uint256 totalDue, uint256 processingCount)\\n    {\\n        totalDue = 0;\\n        processingCount = 0;\\n        erc20Balance = _collateral.balanceOf(_assetSender);\\n\\n        \/\/ Since we can\u0027t iterate over mappings directly, we\u0027ll check the current epoch\u0027s redemption requests\\n        uint256 exchangeRate = _epochToExchangeRate[currentEpoch];\\n\\n        \/\/ We need to track this through events or a separate counter since we can\u0027t iterate mappings\\n        \/\/ For now, we\u0027ll return the balance and total due based on current epoch\\n        if (exchangeRate \u003e 0) {\\n            \/\/ The actual processing count would need to be tracked separately\\n            \/\/ This is a simplified implementation\\n            totalDue = erc20Balance;\\n            processingCount = 0;\\n        }\\n\\n        return (erc20Balance, totalDue, processingCount);\\n    }\\n\\n    \/**\\n     * @notice Updates the collateral token contract address\\n     * @dev Can only be called by an account with the OPERATOR_ADMIN role\\n     * @param collateral The address of the new collateral token contract\\n     *\/\\n    function setCollateralContract(address collateral) external onlyRole(OPERATOR_ADMIN) {\\n        require(collateral != address(0), \\\"CollateralZeroAddress\\\");\\n        address oldCollateral = address(_collateral);\\n        _collateral = IERC20(collateral);\\n        emit CollateralContractSet(oldCollateral, collateral);\\n    }\\n}\\n\"},\"settings.json\":{\"content\":\"{\\\"viaIR\\\":true,\\\"optimizer\\\":{\\\"enabled\\\":true,\\\"runs\\\":200,\\\"details\\\":{\\\"yul\\\":true,\\\"yulDetails\\\":{\\\"stackAllocation\\\":true}}},\\\"outputSelection\\\":{\\\"*\\\":{\\\"*\\\":[\\\"evm.bytecode\\\",\\\"evm.deployedBytecode\\\",\\\"devdoc\\\",\\\"userdoc\\\",\\\"metadata\\\",\\\"abi\\\"]}}}\"}}}'
